<?php
declare(strict_types=1); require dirname(__DIR__,2).'/includes/bootstrap.php'; require_permission('video_categories.manage');
$cats=db()->query('SELECT c.id,c.name,c.slug,c.status,c.capacity_limit,(SELECT COUNT(*) FROM qr_campaigns q WHERE q.category_id=c.id) qr_count,(SELECT COUNT(*) FROM spot_campaigns s WHERE s.category_id=c.id) spot_count FROM video_categories c ORDER BY c.name')->fetchAll();$pageTitle='Manage categories';$pageSubtitle='View, edit and control category buckets';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="panel-head"><h2>Category buckets</h2><a class="btn" href="<?=e(app_url('/admin/categories/index.php'))?>">Create category</a></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>QR usage</th><th>Master spots</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><strong><?=e($c['name'])?></strong><br><small><?=e($c['slug'])?></small></td><td><?=e($c['qr_count'])?> / <?=e($c['capacity_limit'])?></td><td><?=e($c['spot_count'])?></td><td><span class="badge <?=strtolower(e($c['status']))?>"><?=e($c['status'])?></span></td><td class="actions"><a class="btn small secondary" href="<?=e(app_url('/admin/categories/view.php?id='.$c['id']))?>">View summary</a><a class="btn small secondary" href="<?=e(app_url('/admin/categories/edit.php?id='.$c['id']))?>">Edit</a></td></tr><?php endforeach?></tbody></table><?php if(!$cats):?><div class="empty">No categories configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
